'use client'

import React, { useRef, useEffect } from 'react'
import { cn } from '@/lib/utils'
import { attachGpuGate, deferUntilVisible } from '@/lib/gpu-runtime'
import { getOptimizedImageUrl } from '@/lib/next-image-url'
import { logger } from '@/utils/logger'
import type { OrbSmoothProps } from './types'
import { useOrbAudio } from './use-orb-audio'
import {
  CLEAR_WGSL,
  SPLAT_WGSL,
  ADVECTION_WGSL,
  DIVERGENCE_WGSL,
  CURL_WGSL,
  VORTICITY_WGSL,
  PRESSURE_WGSL,
  GRAD_SUB_WGSL,
  BLUR_WGSL,
} from './sim.wgsl'
import { DISPLAY_WGSL } from './display.wgsl'

export function OrbSmooth({
  textureUrl = 'https://avatars.spaceui.one/v1?name=orion&variant=shaula&format=svg',
  audioMode,
  audioElement,
  audioSrc,
  useMicrophone = false,
  circleSize = 1,
  alpha = 1,
  animated = true,
  sphereScale = 0.9,
  spherePower = 1.1,
  fbmScale = 3.25,
  fbmPower = 2.75,
  fbmAmplitude = 0.65,
  fbmSpeed = 4.5,
  noiseSpeed = 0.25,
  noiseAmplitude = 0.15,
  noiseScale = 0.65,
  exposure = 0.15,
  contrast = 0,
  saturation = 1,
  fadeInDuration = 0,
  ringColorOpacity = 0.25,
  fluidColor = [1, 1, 1],
  fluidColorOpacity = 0.1,
  grainOpacity = 0.67,
  grainAnimated = true,
  watercolorStrength = 0.5,
  timeScale = 1.4,
  overallSoundScale = 1,
  onTextureReady,
  size = 240,
  className = '',
  style,
}: OrbSmoothProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const audioAnalyzerRef = useOrbAudio(audioMode, audioElement, audioSrc, useMicrophone)
  const onTextureReadyRef = useRef(onTextureReady)
  onTextureReadyRef.current = onTextureReady

  const propsRef = useRef({
    textureUrl,
    animated,
    sphereScale,
    spherePower,
    fbmScale,
    fbmPower,
    fbmAmplitude,
    fbmSpeed,
    noiseSpeed,
    noiseAmplitude,
    noiseScale,
    exposure,
    contrast,
    saturation,
    fadeInDuration,
    ringColorOpacity,
    fluidColor,
    fluidColorOpacity,
    grainOpacity,
    grainAnimated,
    watercolorStrength,
    timeScale,
    overallSoundScale,
    circleSize,
    alpha,
  })
  propsRef.current = {
    textureUrl,
    animated,
    sphereScale,
    spherePower,
    fbmScale,
    fbmPower,
    fbmAmplitude,
    fbmSpeed,
    noiseSpeed,
    noiseAmplitude,
    noiseScale,
    exposure,
    contrast,
    saturation,
    fadeInDuration,
    ringColorOpacity,
    fluidColor,
    fluidColorOpacity,
    grainOpacity,
    grainAnimated,
    watercolorStrength,
    timeScale,
    overallSoundScale,
    circleSize,
    alpha,
  }

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    let cancelled = false
    let stop: (() => void) | undefined
    let disposeGpu: (() => void) | undefined
    let disposeGate: (() => void) | undefined
    let disposeDefer: (() => void) | undefined

    async function mount() {
      const { init, effect, surface, frame, pingPong, sampler, target } = await import('vgpu')
      if (cancelled || !canvasRef.current) return
      const gpu = await init()
      if (cancelled) {
        gpu.dispose()
        return
      }

      let raf = 0
      let render = () => {}
      const gate = attachGpuGate(canvas, (paused) => {
        if (paused) cancelAnimationFrame(raf)
        else if (!cancelled) raf = requestAnimationFrame(render)
      })
      disposeGate = gate.dispose
      const low = gate.state.lowPower
      const lowPower = low
      if (low) {
        canvas.width = 160
        canvas.height = 160
      }
      const simRes = low ? 32 : 128
      const dyeRes = low ? 64 : 256
      const floatFmt = 'rgba16float' as const
      const lin = sampler(gpu, { minFilter: 'linear', magFilter: 'linear' })
      const near = sampler(gpu, { minFilter: 'nearest', magFilter: 'nearest' })
      const velocity = pingPong(gpu, simRes, simRes, { format: floatFmt, clearColor: [0, 0, 0, 1] })
      const density = pingPong(gpu, dyeRes, dyeRes, { format: floatFmt, clearColor: [0, 0, 0, 1] })
      const pressure = pingPong(gpu, simRes, simRes, { format: floatFmt, clearColor: [0, 0, 0, 1] })
      const divergence = target(gpu, { size: [simRes, simRes], format: floatFmt, clearColor: [0, 0, 0, 1] })
      const curl = target(gpu, { size: [simRes, simRes], format: floatFmt, clearColor: [0, 0, 0, 1] })
      const canvasSurface = surface(gpu, canvasRef.current, { format: 'bgra8unorm', alphaMode: 'premultiplied' })

      const clearFx = effect(gpu, CLEAR_WGSL)
      const splatFx = effect(gpu, SPLAT_WGSL)
      const advectFx = effect(gpu, ADVECTION_WGSL)
      const divFx = effect(gpu, DIVERGENCE_WGSL)
      const curlFx = effect(gpu, CURL_WGSL)
      const vortFx = effect(gpu, VORTICITY_WGSL)
      const pressFx = effect(gpu, PRESSURE_WGSL)
      const gradFx = effect(gpu, GRAD_SUB_WGSL)
      const blurFx = effect(gpu, BLUR_WGSL)
      const displayFx = effect(gpu, DISPLAY_WGSL, { blend: 'premultiplied' })

      let bgTex = gpu.device.createTexture({
        size: [1, 1],
        format: 'rgba8unorm',
        usage: ['texture_binding', 'copy_dst', 'render_attachment'],
      })
      gpu.gpu.queue.writeTexture(
        { texture: bgTex.gpu },
        new Uint8Array([255, 255, 255, 255]),
        { bytesPerRow: 4 },
        [1, 1],
      )
      let texSize: [number, number] = [1, 1]
      let currentUrl = propsRef.current.textureUrl

      const loadImage = (url: string) => {
        const img = new Image()
        img.crossOrigin = 'anonymous'
        img.onload = () => {
          const next = gpu.device.createTexture({
            size: [img.width, img.height],
            format: 'rgba8unorm',
            usage: ['texture_binding', 'copy_dst', 'render_attachment'],
          })
          gpu.gpu.queue.copyExternalImageToTexture({ source: img }, { texture: next.gpu }, [img.width, img.height])
          bgTex = next
          texSize = [img.width, img.height]
          onTextureReadyRef.current?.(url)
        }
        img.src = url ? getOptimizedImageUrl(url, { width: 512 }) : url
      }
      loadImage(currentUrl || '')

      const blit = (
        fx: ReturnType<typeof effect>,
        dest: { color?: unknown } & object,
        extra?: Record<string, unknown>,
      ) => {
        if (extra) fx.set(extra)
        frame(gpu, (f) => f.pass({ target: dest as never, clear: false }, fx))
      }

      const audioAverage = [0, 0, 0, 0]
      const audioAverageInput = [0, 0, 0, 0]
      const cumulativeAudio = [0, 0, 0, 0]
      let time = 0
      let last = performance.now()
      const texelSize = 1 / simRes
      const dyeTexel = 1 / dyeRes

      let lastDraw = 0
      render = () => {
        if (cancelled || gate.state.paused) return
        const cur = propsRef.current
        const now = performance.now()
        if (gate.frameMs && now - lastDraw < gate.frameMs) {
          if (cur.animated) raf = requestAnimationFrame(render)
          return
        }
        lastDraw = now
        if (cur.textureUrl !== currentUrl) {
          currentUrl = cur.textureUrl
          loadImage(currentUrl || '')
        }
        const dt = Math.min((now - last) / 1000, 0.05)
        last = now
        time += dt * cur.timeScale

        const analyzer = audioAnalyzerRef.current
        let splats: Array<{ x: number; y: number; dx: number; dy: number }> = []
        if (analyzer) {
          analyzer.update()
          const stepAudio = [
            analyzer.lowAvg / 255,
            analyzer.midAvg / 255,
            analyzer.highAvg / 255,
            analyzer.allAvg / 255,
          ]
          for (let i = 0; i < 4; i++) {
            const val = stepAudio[i] * cur.overallSoundScale
            cumulativeAudio[i] += val * (60 * dt * cur.timeScale) * 0.25
            audioAverage[i] += (val - audioAverage[i]) * 0.55
            audioAverageInput[i] += (val - audioAverageInput[i]) * 0.45
          }
          const splatX = -0.2 * Math.sin(0.5 * cumulativeAudio[1]) + 0.5
          const splatY = 0.15 * Math.cos(0.38 * cumulativeAudio[0]) + 0.5
          if (Math.abs(audioAverage[3]) > 1e-4) {
            splats.push({
              x: 0.5 + 0.1 * splatX,
              y: 0.5 + 0.1 * splatY,
              dx: (splatX - 0.5) * 12,
              dy: (splatY - 0.5) * 12,
            })
          }
        }

        const cum = [cumulativeAudio[0], cumulativeAudio[1], cumulativeAudio[2], cumulativeAudio[3]] as const
        const avg = [audioAverage[0], audioAverage[1], audioAverage[2], audioAverage[3]] as const

        if (!lowPower) {
          for (const s of splats) {
            const splatParams = {
              point: [s.x, s.y],
              color: [s.dx, s.dy, 1, 1],
              cumulativeAudio: cum,
              audioAverage: avg,
              radius: 1.5,
              time,
              aspectRatio: 1,
            }
            splatFx.set({ uTarget: velocity.read.color, samp: lin, params: splatParams })
            blit(splatFx, velocity.write)
            velocity.swap()
            splatFx.set({ uTarget: density.read.color, samp: lin, params: splatParams })
            blit(splatFx, density.write)
            density.swap()
          }

          curlFx.set({ uVelocity: velocity.read.color, samp: near, params: { texelSize: [texelSize, texelSize] } })
          blit(curlFx, curl)

          vortFx.set({
            uVelocity: velocity.read.color,
            uCurl: curl.color,
            samp: lin,
            params: { texelSize: [texelSize, texelSize], curl: 0, dt: 0.016 },
          })
          blit(vortFx, velocity.write)
          velocity.swap()

          divFx.set({ uVelocity: velocity.read.color, samp: near, params: { texelSize: [texelSize, texelSize] } })
          blit(divFx, divergence)

          clearFx.set({ uTexture: pressure.read.color, samp: near, params: { value: 0.97 } })
          blit(clearFx, pressure.write)
          pressure.swap()

          for (let i = 0; i < 3; i++) {
            pressFx.set({
              uPressure: pressure.read.color,
              uDivergence: divergence.color,
              samp: near,
              params: { texelSize: [texelSize, texelSize] },
            })
            blit(pressFx, pressure.write)
            pressure.swap()
          }

          gradFx.set({
            uPressure: pressure.read.color,
            uVelocity: velocity.read.color,
            samp: lin,
            params: { texelSize: [texelSize, texelSize] },
          })
          blit(gradFx, velocity.write)
          velocity.swap()

          advectFx.set({
            uVelocity: velocity.read.color,
            uSource: velocity.read.color,
            samp: lin,
            params: {
              texelSize: [texelSize, texelSize],
              dyeTexelSize: [texelSize, texelSize],
              dt: 0.016,
              dissipation: 0.98,
            },
          })
          blit(advectFx, velocity.write)
          velocity.swap()

          advectFx.set({
            uVelocity: velocity.read.color,
            uSource: density.read.color,
            samp: lin,
            params: {
              texelSize: [texelSize, texelSize],
              dyeTexelSize: [dyeTexel, dyeTexel],
              dt: 0.016,
              dissipation: 0.98,
            },
          })
          blit(advectFx, density.write)
          density.swap()

          for (const dir of [
            [1.2, 0],
            [0, 1.2],
          ]) {
            blurFx.set({
              uTexture: density.read.color,
              samp: lin,
              params: { simRes: [simRes, simRes], direction: dir },
            })
            blit(blurFx, density.write)
            density.swap()
          }
        }

        const w = canvasRef.current?.width || size
        const h = canvasRef.current?.height || size
        displayFx.set({
          uTexture: bgTex,
          uFluidSimTexture: density.read.color,
          samp: lin,
          params: {
            uAudioAverage: avg,
            uAudioAverageInput: audioAverageInput,
            uCumulativeAudio: cum,
            uFluidColor: [cur.fluidColor[0], cur.fluidColor[1], cur.fluidColor[2], 1],
            uResolution: [w, h],
            uTextureResolution: texSize,
            uTime: time,
            uCircleSize: cur.circleSize,
            uAlpha: cur.alpha,
            uExposure: cur.exposure,
            uContrast: cur.contrast,
            uSaturation: cur.saturation,
            uNoiseOpacity: lowPower ? 0 : cur.grainOpacity,
            uAnimatedNoise: lowPower ? 0 : cur.grainAnimated ? 1 : 0,
            uNoiseSpeed: cur.noiseSpeed,
            uNoiseAmplitude: cur.noiseAmplitude,
            uNoiseScale: cur.noiseScale,
            uSphereScale: cur.sphereScale,
            uSpherePower: cur.spherePower,
            uFluidColorOpacity: cur.fluidColorOpacity,
            uRingColorOpacity: cur.ringColorOpacity,
            uFbmScale: cur.fbmScale,
            uFbmPower: cur.fbmPower,
            uFbmAmplitude: cur.fbmAmplitude,
            uFbmSpeed: cur.fbmSpeed,
            uFadeInDuration: cur.fadeInDuration,
            uDpr: 1,
            uWatercolorStrength: lowPower ? 0 : cur.watercolorStrength,
          },
        })
        frame(gpu, (f) => f.pass({ target: canvasSurface, clear: [0, 0, 0, 0] }, displayFx))

        if (cur.animated) raf = requestAnimationFrame(render)
      }

      raf = requestAnimationFrame(render)
      stop = () => cancelAnimationFrame(raf)
      disposeGpu = () => gpu.dispose()
    }

    disposeDefer = deferUntilVisible(canvas, () => {
      mount().catch((error) => logger.error('OrbSmooth WebGPU init failed:', error))
    })
    return () => {
      cancelled = true
      disposeDefer?.()
      stop?.()
      disposeGate?.()
      disposeGpu?.()
    }
  }, [])

  return (
    <canvas
      ref={canvasRef}
      width={512}
      height={512}
      className={cn('aspect-square', className)}
      style={{
        width: size !== undefined ? `${size}px` : '100%',
        height: size !== undefined ? `${size}px` : '100%',
        display: 'block',
        ...style,
      }}
    />
  )
}

export const CLEAR_WGSL = /* wgsl */ `
@group(0) @binding(0) var uTexture: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
struct Params { value: f32 }
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  return params.value * textureSampleLevel(uTexture, samp, uv, 0.0);
}
`

export const SPLAT_WGSL = /* wgsl */ `
@group(0) @binding(0) var uTarget: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
struct Params {
  point: vec2f,
  color: vec4f,
  cumulativeAudio: vec4f,
  audioAverage: vec4f,
  radius: f32,
  time: f32,
  aspectRatio: f32,
}
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  var p = uv - vec2f(0.5);
  p *= params.radius;
  let dist = sqrt(dot(p, p));
  let pTime = params.time * 0.25 + params.cumulativeAudio.w * 0.15;
  let pDist = (dist * 2.0 - pTime) % 1.0;
  let width = 0.15;
  let pulse = smoothstep(0.0, width, pDist) - smoothstep(width, width * 2.0, pDist);
  let splat = pulse * (params.audioAverage.x * 30.0) * clamp(dist, 0.0, 1.0) * params.color.xyz;
  let base = textureSampleLevel(uTarget, samp, uv, 0.0).xyz;
  return vec4f(base + splat, 1.0);
}
`

export const ADVECTION_WGSL = /* wgsl */ `
@group(0) @binding(0) var uVelocity: texture_2d<f32>;
@group(0) @binding(1) var uSource: texture_2d<f32>;
@group(0) @binding(2) var samp: sampler;
struct Params { texelSize: vec2f, dyeTexelSize: vec2f, dt: f32, dissipation: f32 }
@group(0) @binding(3) var<uniform> params: Params;
fn bilerp(tex: texture_2d<f32>, uv: vec2f, tsize: vec2f) -> vec4f {
  let st = uv / tsize - 0.5;
  let iuv = floor(st);
  let fuv = fract(st);
  let a = textureSampleLevel(tex, samp, (iuv + vec2f(0.5, 0.5)) * tsize, 0.0);
  let b = textureSampleLevel(tex, samp, (iuv + vec2f(1.5, 0.5)) * tsize, 0.0);
  let c = textureSampleLevel(tex, samp, (iuv + vec2f(0.5, 1.5)) * tsize, 0.0);
  let d = textureSampleLevel(tex, samp, (iuv + vec2f(1.5, 1.5)) * tsize, 0.0);
  return mix(mix(a, b, fuv.x), mix(c, d, fuv.x), fuv.y);
}
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let coord = uv - params.dt * bilerp(uVelocity, uv, params.texelSize).xy * params.texelSize;
  var color = params.dissipation * bilerp(uSource, coord, params.dyeTexelSize);
  color.w = 1.0;
  return color;
}
`

export const DIVERGENCE_WGSL = /* wgsl */ `
@group(0) @binding(0) var uVelocity: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
struct Params { texelSize: vec2f }
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.texelSize;
  var L = textureSampleLevel(uVelocity, samp, uv - vec2f(t.x, 0.0), 0.0).x;
  var R = textureSampleLevel(uVelocity, samp, uv + vec2f(t.x, 0.0), 0.0).x;
  var T = textureSampleLevel(uVelocity, samp, uv + vec2f(0.0, t.y), 0.0).y;
  var B = textureSampleLevel(uVelocity, samp, uv - vec2f(0.0, t.y), 0.0).y;
  let C = textureSampleLevel(uVelocity, samp, uv, 0.0).xy;
  if ((uv - vec2f(t.x, 0.0)).x < 0.0) { L = -C.x; }
  if ((uv + vec2f(t.x, 0.0)).x > 1.0) { R = -C.x; }
  if ((uv + vec2f(0.0, t.y)).y > 1.0) { T = -C.y; }
  if ((uv - vec2f(0.0, t.y)).y < 0.0) { B = -C.y; }
  let div = 0.5 * (R - L + T - B);
  return vec4f(div, 0.0, 0.0, 1.0);
}
`

export const CURL_WGSL = /* wgsl */ `
@group(0) @binding(0) var uVelocity: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
struct Params { texelSize: vec2f }
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.texelSize;
  let L = textureSampleLevel(uVelocity, samp, uv - vec2f(t.x, 0.0), 0.0).y;
  let R = textureSampleLevel(uVelocity, samp, uv + vec2f(t.x, 0.0), 0.0).y;
  let T = textureSampleLevel(uVelocity, samp, uv + vec2f(0.0, t.y), 0.0).x;
  let B = textureSampleLevel(uVelocity, samp, uv - vec2f(0.0, t.y), 0.0).x;
  let vorticity = R - L - T + B;
  return vec4f(0.5 * vorticity, 0.0, 0.0, 1.0);
}
`

export const VORTICITY_WGSL = /* wgsl */ `
@group(0) @binding(0) var uVelocity: texture_2d<f32>;
@group(0) @binding(1) var uCurl: texture_2d<f32>;
@group(0) @binding(2) var samp: sampler;
struct Params { texelSize: vec2f, curl: f32, dt: f32 }
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.texelSize;
  let L = textureSampleLevel(uCurl, samp, uv - vec2f(t.x, 0.0), 0.0).x;
  let R = textureSampleLevel(uCurl, samp, uv + vec2f(t.x, 0.0), 0.0).x;
  let T = textureSampleLevel(uCurl, samp, uv + vec2f(0.0, t.y), 0.0).x;
  let B = textureSampleLevel(uCurl, samp, uv - vec2f(0.0, t.y), 0.0).x;
  let C = textureSampleLevel(uCurl, samp, uv, 0.0).x;
  var force = 0.5 * vec2f(abs(T) - abs(B), abs(R) - abs(L));
  force /= length(force) + 0.0001;
  force *= params.curl * C;
  force.y *= -1.0;
  let vel = textureSampleLevel(uVelocity, samp, uv, 0.0).xy;
  return vec4f(vel + force * params.dt, 0.0, 1.0);
}
`

export const PRESSURE_WGSL = /* wgsl */ `
@group(0) @binding(0) var uPressure: texture_2d<f32>;
@group(0) @binding(1) var uDivergence: texture_2d<f32>;
@group(0) @binding(2) var samp: sampler;
struct Params { texelSize: vec2f }
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.texelSize;
  let L = textureSampleLevel(uPressure, samp, uv - vec2f(t.x, 0.0), 0.0).x;
  let R = textureSampleLevel(uPressure, samp, uv + vec2f(t.x, 0.0), 0.0).x;
  let T = textureSampleLevel(uPressure, samp, uv + vec2f(0.0, t.y), 0.0).x;
  let B = textureSampleLevel(uPressure, samp, uv - vec2f(0.0, t.y), 0.0).x;
  let divergence = textureSampleLevel(uDivergence, samp, uv, 0.0).x;
  let pressure = (L + R + B + T - divergence) * 0.25;
  return vec4f(pressure, 0.0, 0.0, 1.0);
}
`

export const GRAD_SUB_WGSL = /* wgsl */ `
@group(0) @binding(0) var uPressure: texture_2d<f32>;
@group(0) @binding(1) var uVelocity: texture_2d<f32>;
@group(0) @binding(2) var samp: sampler;
struct Params { texelSize: vec2f }
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.texelSize;
  let L = textureSampleLevel(uPressure, samp, uv - vec2f(t.x, 0.0), 0.0).x;
  let R = textureSampleLevel(uPressure, samp, uv + vec2f(t.x, 0.0), 0.0).x;
  let T = textureSampleLevel(uPressure, samp, uv + vec2f(0.0, t.y), 0.0).x;
  let B = textureSampleLevel(uPressure, samp, uv - vec2f(0.0, t.y), 0.0).x;
  var velocity = textureSampleLevel(uVelocity, samp, uv, 0.0).xy;
  velocity -= vec2f(R - L, T - B);
  return vec4f(velocity, 0.0, 1.0);
}
`

export const BLUR_WGSL = /* wgsl */ `
@group(0) @binding(0) var uTexture: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
struct Params { simRes: vec2f, direction: vec2f }
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let off1 = 1.3846153846 * params.direction;
  let off2 = 3.2307692308 * params.direction;
  var color = textureSampleLevel(uTexture, samp, uv, 0.0) * 0.2270270270;
  color += textureSampleLevel(uTexture, samp, uv + off1 / params.simRes, 0.0) * 0.3162162162;
  color += textureSampleLevel(uTexture, samp, uv - off1 / params.simRes, 0.0) * 0.3162162162;
  color += textureSampleLevel(uTexture, samp, uv + off2 / params.simRes, 0.0) * 0.0702702703;
  color += textureSampleLevel(uTexture, samp, uv - off2 / params.simRes, 0.0) * 0.0702702703;
  return color;
}
`

export const DISPLAY_WGSL = /* wgsl */ `
@group(0) @binding(0) var uTexture: texture_2d<f32>;
@group(0) @binding(1) var uFluidSimTexture: texture_2d<f32>;
@group(0) @binding(2) var samp: sampler;
struct Params {
  uAudioAverage: vec4f,
  uAudioAverageInput: vec4f,
  uCumulativeAudio: vec4f,
  uFluidColor: vec4f,
  uResolution: vec2f,
  uTextureResolution: vec2f,
  uTime: f32,
  uCircleSize: f32,
  uAlpha: f32,
  uExposure: f32,
  uContrast: f32,
  uSaturation: f32,
  uNoiseOpacity: f32,
  uAnimatedNoise: f32,
  uNoiseSpeed: f32,
  uNoiseAmplitude: f32,
  uNoiseScale: f32,
  uSphereScale: f32,
  uSpherePower: f32,
  uFluidColorOpacity: f32,
  uRingColorOpacity: f32,
  uFbmScale: f32,
  uFbmPower: f32,
  uFbmAmplitude: f32,
  uFbmSpeed: f32,
  uFadeInDuration: f32,
  uDpr: f32,
  uWatercolorStrength: f32,
}
@group(0) @binding(3) var<uniform> params: Params;

fn getCoverUv(uv: vec2f, containerRes: vec2f, textureRes: vec2f) -> vec2f {
  let containerAspect = containerRes.x / containerRes.y;
  let textureAspect = textureRes.x / max(textureRes.y, 0.0001);
  var scale = vec2f(1.0);
  if (containerAspect > textureAspect) { scale.y = textureAspect / containerAspect; }
  else { scale.x = containerAspect / textureAspect; }
  return (uv - 0.5) * scale + 0.5;
}

fn permute(x: vec3f) -> vec3f { return ((x * 34.0 + 1.0) * x) % 289.0; }
fn permute4(x: vec4f) -> vec4f { return ((x * 34.0 + 1.0) * x) % 289.0; }
fn taylorInvSqrt(r: vec4f) -> vec4f { return 1.79284291400159 - 0.85373472095314 * r; }

fn snoise(v: vec3f) -> f32 {
  let C = vec2f(1.0 / 6.0, 1.0 / 3.0);
  let D = vec4f(0.0, 0.5, 1.0, 2.0);
  var i = floor(v + dot(v, C.yyy));
  let x0 = v - i + dot(i, C.xxx);
  let g = step(x0.yzx, x0.xyz);
  let l = 1.0 - g;
  let i1 = min(g.xyz, l.zxy);
  let i2 = max(g.xyz, l.zxy);
  let x1 = x0 - i1 + C.xxx;
  let x2 = x0 - i2 + 2.0 * C.xxx;
  let x3 = x0 - 1.0 + 3.0 * C.xxx;
  i = i % 289.0;
  var pv = permute4(permute4(permute4(i.z + vec4f(0.0, i1.z, i2.z, 1.0)) + i.y + vec4f(0.0, i1.y, i2.y, 1.0)) + i.x + vec4f(0.0, i1.x, i2.x, 1.0));
  let n_ = 1.0 / 7.0;
  let ns = n_ * D.wyz - D.xzx;
  let j = pv - 49.0 * floor(pv * ns.z * ns.z);
  let x_ = floor(j * ns.z);
  let y_ = floor(j - 7.0 * x_);
  let x = x_ * ns.x + ns.yyyy;
  let y = y_ * ns.x + ns.yyyy;
  let h = 1.0 - abs(x) - abs(y);
  let b0 = vec4f(x.xy, y.xy);
  let b1 = vec4f(x.zw, y.zw);
  let s0 = floor(b0) * 2.0 + 1.0;
  let s1 = floor(b1) * 2.0 + 1.0;
  let sh = -step(h, vec4f(0.0));
  let a0 = b0.xzyw + s0.xzyw * sh.xxyy;
  let a1 = b1.xzyw + s1.xzyw * sh.zzww;
  var p0 = vec3f(a0.xy, h.x);
  var p1 = vec3f(a0.zw, h.y);
  var p2 = vec3f(a1.xy, h.z);
  var p3 = vec3f(a1.zw, h.w);
  let norm = taylorInvSqrt(vec4f(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  var m = max(0.6 - vec4f(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), vec4f(0.0));
  m = m * m;
  return 42.0 * dot(m * m, vec4f(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
}

fn contrastFn(color: vec3f, value: f32) -> vec3f {
  return clamp(0.5 + (1.0 + value) * (color - 0.5), vec3f(0.0), vec3f(1.0));
}
fn exposureFn(color: vec3f, value: f32) -> vec3f { return (1.0 + value) * color; }
fn saturationFn(rgb: vec3f, adjustment: f32) -> vec3f {
  let W = vec3f(0.2125, 0.7154, 0.0721);
  let intensity = vec3f(dot(rgb, W));
  return mix(intensity, rgb, adjustment);
}
fn blendOverlay(base: f32, blend: f32) -> f32 {
  if (base < 0.5) { return 2.0 * base * blend; }
  return 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
}
fn blendOverlayVec(base: vec3f, blend: vec3f) -> vec3f {
  return vec3f(blendOverlay(base.r, blend.r), blendOverlay(base.g, blend.g), blendOverlay(base.b, blend.b));
}
fn blendHardLight(base: vec3f, blend: vec3f, opacity: f32) -> vec3f {
  let result = blendOverlayVec(blend, base);
  return result * opacity + base * (1.0 - opacity);
}
fn random2(st: vec2f) -> f32 {
  return fract(sin(dot(st, vec2f(12.9898, 78.233))) * 43758.5453123);
}
fn filmGrainNoise(uv: vec2f) -> f32 {
  return fract(sin(dot(uv, vec2f(12.9898, 78.233))) * 43758.5453);
}
fn noise2d(st: vec2f) -> f32 {
  let i = floor(st);
  let f = fract(st);
  let a = random2(i);
  let b = random2(i + vec2f(1.0, 0.0));
  let c = random2(i + vec2f(0.0, 1.0));
  let d = random2(i + vec2f(1.0, 1.0));
  let u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}
fn fbm(st_in: vec2f) -> f32 {
  var st = st_in;
  var v = 0.0;
  var a = 0.5;
  let shift = vec2f(100.0);
  let rot = mat2x2f(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (var i = 0; i < 4; i++) {
    v += a * noise2d(st);
    st = rot * st * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

@fragment fn fs_main(@location(0) uv_in: vec2f, @builtin(position) frag: vec4f) -> @location(0) vec4f {
  let vUv = vec2f(1.0 - uv_in.x, 1.0 - uv_in.y);
  var uv = vec2f(1.0 - vUv.x, vUv.y);
  let fluid = textureSampleLevel(uFluidSimTexture, samp, vUv, 0.0).rgb;
  let circleSize = params.uCircleSize - pow(params.uAudioAverageInput.x * 0.75, 3.0) * 0.2;
  var uvDot = (uv - 0.5) * 2.0;
  var d = sqrt(1.0 - clamp(dot(uvDot, uvDot), 0.0, 1.0));
  d = pow(d, params.uSpherePower);
  let normals = vec3f(uvDot, d);
  uvDot /= (vec2f(d) + vec2f(1.0)) * (1.0 / params.uSphereScale);
  uvDot = (uvDot + 1.0) * 0.5;
  uv = uvDot;

  let fbmUv = uv * params.uFbmScale;
  let fbmTime1 = params.uTime * params.uFbmSpeed;
  let fbmTime2 = params.uTime * (params.uFbmSpeed * 0.5) + params.uCumulativeAudio.x * 0.25;
  var q = vec2f(0.0);
  q.x = fbm(fbmUv + 0.00 * fbmTime1);
  q.y = fbm(fbmUv + vec2f(1.0));
  var r = vec2f(0.0);
  r.x = fbm(fbmUv + 1.0 * q + vec2f(91.3, 0.55) + 0.15 * fbmTime2);
  r.y = fbm(fbmUv + 1.0 * q - vec2f(45.33, 1.2) + 0.126 * fbmTime2);
  let f = fbm(fbmUv + r);
  var ffbm = mix(0.8, 0.66, clamp((f * f) * params.uFbmPower, 0.0, 1.0));
  ffbm = mix(ffbm, 0.0, clamp(length(q), 0.0, 1.0));
  ffbm = mix(ffbm, 1.0, clamp(length(r.x), 0.0, 1.0));

  let noiseTime1 = params.uTime * params.uNoiseSpeed * 0.5 + params.uCumulativeAudio.z * 0.1;
  let noiseX = snoise(vec3f(vUv * params.uNoiseScale, noiseTime1));
  let noiseY = snoise(vec3f(vec2f(vUv * params.uNoiseScale + vec2f(54.0)), params.uTime * params.uNoiseSpeed));
  var noiseDisp = vec2f(noiseX, noiseY) * (1.0 + params.uAudioAverage.z * 0.25);

  let circleUv = vUv - 0.5;
  let dist = sqrt(dot(circleUv, circleUv));
  let s = smoothstep(0.5, 0.496, dist);
  let pTime = params.uTime * 0.2 + params.uCumulativeAudio.z * 0.4;
  let pDist = ((dist * 2.0 - pTime) % 1.0 + 1.0) % 1.0;
  var pulse = smoothstep(0.0, 0.75, pDist) - smoothstep(0.75, 1.0, pDist);
  pulse = pow(pulse, 2.0) * params.uAudioAverage.y;

  uv += -fluid.rg * 0.001;
  uv += normals.xy * (ffbm - 0.5) * params.uFbmAmplitude;
  uv += noiseDisp * params.uNoiseAmplitude;
  let wcAmp = clamp(params.uWatercolorStrength, 0.0, 1.0) * 2.0;
  let wcTime = params.uTime * 0.85;
  let wcX = snoise(vec3f(uv + vec2f(0.0, 74.8572), (wcTime + params.uCumulativeAudio.x * 0.05) * 0.3));
  let wcY = snoise(vec3f(uv + vec2f(203.91282, 10.0), (wcTime + params.uCumulativeAudio.z * 0.05) * 0.3));
  uv += vec2f(wcX * 2.0, wcY) * 0.19 * wcAmp;

  let coverUv = getCoverUv(uv, params.uResolution, params.uTextureResolution);
  let gradient = textureSampleLevel(uTexture, samp, coverUv, 0.0).rgb;

  var ringUv = (vUv - 0.5) * 2.0 * (1.0 / params.uCircleSize) * 0.75;
  let ang = atan2(ringUv.y, ringUv.x);
  let len = length(ringUv);
  let ringTime = (-params.uTime * 0.5) - params.uCumulativeAudio.w * 0.2;
  ringUv.x += 1.0 + params.uAudioAverage.y * 1.5 - params.uAudioAverageInput.y * 2.5;
  let noiseScale = 0.65 + params.uAudioAverage.x * 0.4;
  let n0 = snoise(vec3f(ringUv * noiseScale, ringTime * 0.5)) * 0.5 + 0.5;
  let innerRadius = 0.25;
  var cl = cos(ang + ringTime * 2.0) * 0.5 + 0.5;
  let v2 = smoothstep(1.0, mix(innerRadius, 1.0, n0 * 0.5), len);
  let v3 = pow(smoothstep(innerRadius, mix(innerRadius, 1.0, n0 * 0.75), len), 2.0);
  cl = cl * v2 * v3;
  cl = clamp(pow(cl * min(params.uAudioAverage.w * 4.0 + params.uAudioAverageInput.x * 4.0, 1.0), 3.0), 0.0, 1.0);

  var color = gradient + (vec3f(cl) * params.uRingColorOpacity);
  color = blendHardLight(color, params.uFluidColor.xyz, length(fluid) * 0.01 * params.uFluidColorOpacity);
  var grainCoord = floor(frag.xy);
  if (params.uAnimatedNoise > 0.5) {
    let gTime = params.uTime * 0.35;
    let waveX = snoise(vec3f(vUv * 2.5, gTime));
    let waveY = snoise(vec3f(vUv * 2.5 + vec2f(9.1, 0.0), gTime + 1.7));
    grainCoord = floor(frag.xy + vec2f(waveX, waveY) * 12.0);
  }
  var grainVal = filmGrainNoise(grainCoord);
  grainVal = clamp((grainVal - 0.5) * 1.5 + 0.5, 0.0, 1.0);
  let grainBlended = blendOverlayVec(color, vec3f(grainVal));
  color = mix(color, grainBlended, clamp(params.uNoiseOpacity, 0.0, 1.0) * 0.15);
  color = saturationFn(color, params.uSaturation);
  color = contrastFn(color, params.uContrast);
  color = exposureFn(color, params.uExposure);
  let fadeIn = select(1.0, min(params.uTime / params.uFadeInDuration, 1.0), params.uFadeInDuration > 0.0);
  let alpha = s * params.uAlpha * fadeIn;
  color = clamp(color, vec3f(0.0), vec3f(1.0));
  return vec4f(color * alpha, alpha);
}
`

// ============================================
// Audio Analyzer (Web Audio API helper)
// ============================================

import { logger } from '@/utils/logger'

let sharedAudioCtx: AudioContext | null = null

function getOrCreateAudioContext(): AudioContext {
  if (typeof window === 'undefined') {
    throw new Error('AudioContext only available in browser')
  }
  if (!sharedAudioCtx || sharedAudioCtx.state === 'closed') {
    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
    sharedAudioCtx = new AudioCtx()
  }
  return sharedAudioCtx
}

export class AudioAnalyzer {
  audioCtx: AudioContext | null = null
  analyser: AnalyserNode | null = null
  sampleRate: number = 48000
  bufferLength: number = 0
  dataArray: Uint8Array = new Uint8Array(0)
  isElementMode = false

  lowFreqEnd = 200
  midFreqStart = 200
  midFreqEnd = 2000
  highFreqStart = 2000
  highFreqEnd = 20000

  lowAvg = 0
  midAvg = 0
  highAvg = 0
  allAvg = 0
  stream: MediaStream | null = null

  async initMic() {
    try {
      this.stream = await navigator.mediaDevices.getUserMedia({ audio: true })
      this.audioCtx = getOrCreateAudioContext()
      this.analyser = this.audioCtx.createAnalyser()
      this.analyser.fftSize = 256
      this.sampleRate = this.audioCtx.sampleRate
      this.bufferLength = this.analyser.frequencyBinCount
      this.dataArray = new Uint8Array(this.bufferLength)

      const source = this.audioCtx.createMediaStreamSource(this.stream)
      source.connect(this.analyser)

      if (this.audioCtx.state === 'suspended') {
        this.audioCtx.resume()
      }
      return true
    } catch (e) {
      logger.warn('Microphone access denied or error:', e)
      return false
    }
  }

  async initElement(audioElement: HTMLAudioElement) {
    try {
      this.isElementMode = true
      this.audioCtx = getOrCreateAudioContext()
      this.analyser = this.audioCtx.createAnalyser()
      this.analyser.fftSize = 256
      this.sampleRate = this.audioCtx.sampleRate
      this.bufferLength = this.analyser.frequencyBinCount
      this.dataArray = new Uint8Array(this.bufferLength)

      // Reuse existing source on the HTMLAudioElement if already created to prevent InvalidStateError
      const el = audioElement as any
      let source: MediaElementAudioSourceNode
      if (el.__mediaElementSource && el.__audioCtx === this.audioCtx) {
        source = el.__mediaElementSource
      } else {
        source = this.audioCtx.createMediaElementSource(audioElement)
        el.__mediaElementSource = source
        el.__audioCtx = this.audioCtx
      }

      // Connect source to analyser and to speakers
      source.connect(this.analyser)
      this.analyser.connect(this.audioCtx.destination)

      const resumeContext = () => {
        if (this.audioCtx && this.audioCtx.state === 'suspended') {
          this.audioCtx.resume()
        }
      }

      audioElement.addEventListener('play', resumeContext)
      audioElement.addEventListener('playing', resumeContext)
      audioElement.addEventListener('canplay', resumeContext)
      audioElement.addEventListener('timeupdate', resumeContext)

      if (this.audioCtx.state === 'suspended') {
        await this.audioCtx.resume()
      }
      try {
        await audioElement.play()
      } catch {
        // autoplay blocked — analyser still works once the user hits play
      }
      return true
    } catch (e) {
      logger.warn('Audio element routing error:', e)
      return false
    }
  }

  getFrequencyRange(startFreq: number, endFreq: number) {
    const startBin = Math.round((startFreq / (this.sampleRate / 2)) * this.bufferLength)
    const endBin = Math.round((endFreq / (this.sampleRate / 2)) * this.bufferLength)
    return [Math.max(0, startBin), Math.min(this.bufferLength - 1, endBin)]
  }

  getAverageFrequencyRange(startBin: number, endBin: number) {
    let sum = 0
    let count = 0
    for (let i = startBin; i <= endBin; i++) {
      sum += this.dataArray[i]
      count++
    }
    return count > 0 ? sum / count : 0
  }

  update() {
    if (!this.analyser) return
    if (this.audioCtx?.state === 'suspended') {
      this.audioCtx.resume()
    }
    this.analyser.getByteFrequencyData(this.dataArray as any)

    const [lStart, lEnd] = this.getFrequencyRange(0, this.lowFreqEnd)
    const [mStart, mEnd] = this.getFrequencyRange(this.midFreqStart, this.midFreqEnd)
    const [hStart, hEnd] = this.getFrequencyRange(this.highFreqStart, this.highFreqEnd)

    this.lowAvg = this.getAverageFrequencyRange(lStart, lEnd)
    this.midAvg = this.getAverageFrequencyRange(mStart, mEnd)
    this.highAvg = this.getAverageFrequencyRange(hStart, hEnd)
    this.allAvg = this.getAverageFrequencyRange(0, this.bufferLength - 1)
  }

  dispose() {
    if (this.stream) {
      this.stream.getTracks().forEach((t) => t.stop())
      this.stream = null
    }
    if (this.audioCtx && !this.isElementMode && this.audioCtx !== sharedAudioCtx) {
      this.audioCtx.close()
    }
  }
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { AudioAnalyzer } from './audio-analyzer'
import { toastManager } from '@/components/ui/toast'
import type { AudioMode } from './types'

export function useCorsAudioSrc(src: string) {
  const [playSrc, setPlaySrc] = useState(src)

  useEffect(() => {
    let revoke: string | undefined
    if (!src) {
      setPlaySrc('')
      return
    }
    if (src.startsWith('blob:') || src.startsWith('data:') || src.startsWith('/')) {
      setPlaySrc(src)
      return
    }
    fetch(src)
      .then((response) => {
        if (!response.ok) throw new Error('audio fetch failed')
        return response.blob()
      })
      .then((blob) => {
        revoke = URL.createObjectURL(blob)
        setPlaySrc(revoke)
      })
      .catch(() => setPlaySrc(src))
    return () => {
      if (revoke) URL.revokeObjectURL(revoke)
    }
  }, [src])

  return playSrc
}

export function useOrbAudio(
  audioMode: AudioMode | undefined,
  audioElement: React.RefObject<HTMLAudioElement | null> | undefined,
  audioSrc?: string,
  useMicrophone?: boolean,
) {
  const analyzerRef = useRef<AudioAnalyzer | null>(null)

  useEffect(() => {
    const mode = audioMode || (useMicrophone ? 'mic' : 'ambient')
    let cancelled = false
    let timer = 0

    const release = () => {
      analyzerRef.current?.dispose()
      analyzerRef.current = null
    }

    async function attachFile() {
      const el = audioElement?.current
      if (cancelled) return
      if (!el || (!el.src && !audioSrc)) {
        timer = window.setTimeout(attachFile, 120)
        return
      }
      if (audioSrc && !el.src) el.src = audioSrc
      const analyzer = new AudioAnalyzer()
      const ok = await analyzer.initElement(el)
      if (cancelled) {
        analyzer.dispose()
        return
      }
      if (ok) analyzerRef.current = analyzer
    }

    async function attachMic() {
      const analyzer = new AudioAnalyzer()
      const ok = await analyzer.initMic()
      if (cancelled) {
        analyzer.dispose()
        return
      }
      if (ok) analyzerRef.current = analyzer
      else {
        toastManager.add({
          type: 'warning',
          title: 'Microphone access denied',
          description: 'Please allow microphone access to enable audio reactivity.',
        })
      }
    }

    release()
    if (mode === 'mic') attachMic()
    else if (mode === 'file') attachFile()

    return () => {
      cancelled = true
      window.clearTimeout(timer)
      release()
    }
  }, [audioMode, audioElement, audioSrc, useMicrophone])

  return analyzerRef
}
